type Item = { type: string };

const basePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const base = basePremiumOf(items);

  return Math.ceil(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

